+// API keys and roles. Pure rules: the HTTP layer passes the request in.
+
+export const ROLES = Object.freeze(["viewer", "cook", "manager"]);
+
+// Non-GET requests a cook may make; managers may make any request.
+const COOK_WRITES = [
+  ["POST", /^\/recipes\/[^/]+\/cook$/],
+  ["POST", /^\/batches\/[^/]+\/waste$/],
+  ["POST", /^\/temperatures$/],
+  ["POST", /^\/stocktakes\/[^/]+\/counts$/],
+];
+
+/** The apiKeys entry for a request's Authorization header, or null. */
+export function findKey(store, header) {
+  const m = /^Bearer\s+(\S+)\s*$/i.exec(String(header ?? ""));
+  if (!m) return null;
+  return (store.data.apiKeys ?? []).find((k) => k.key === m[1]) ?? null;
+}
+
+/** Whether `role` may make the request `method` `path`. */
+export function mayDo(role, method, path) {
+  if (role === "manager") return true;
+  if (path === "/audit") return false;
+  if (method === "GET") return role === "viewer" || role === "cook";
+  return role === "cook" && COOK_WRITES.some(([m, re]) => m === method && re.test(path));
+}
