@@ -0,0 +1,39 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app, bearer } from "./helpers.js";
+
+test("missing or unknown keys are 401", async () => {
+  const { raw } = app();
+  const a = await raw({ path: "/items" });
+  assert.equal(a.status, 401);
+  assert.equal(a.body.error.code, "unauthorized");
+  assert.equal((await raw({ path: "/items", headers: bearer("nope") })).status, 401);
+});
+
+test("viewers read only, cooks cook, managers do everything", async () => {
+  const { raw, store } = app();
+  assert.equal((await raw({ path: "/items", headers: bearer("viewer-key-1") })).status, 200);
+  const denied = await raw({ method: "POST", path: "/recipes/1/cook", headers: bearer("viewer-key-1"), body: { portions: 1 } });
+  assert.equal(denied.status, 403);
+  assert.equal(denied.body.error.code, "forbidden");
+  const cook = bearer("cook-key-1");
+  assert.equal((await raw({ method: "POST", path: "/recipes/1/cook", headers: cook, body: { portions: 1 } })).status, 200);
+  assert.equal((await raw({ method: "POST", path: "/orders", headers: cook, body: {} })).status, 403);
+  assert.equal((await raw({ method: "POST", path: "/stocktakes", headers: cook, body: { location: "dry" } })).status, 403);
+  assert.equal((await raw({ method: "POST", path: "/stocktakes", headers: bearer("manager-key-1"), body: { location: "dry" } })).status, 201);
+  assert.equal((await raw({ path: "/audit", headers: cook })).status, 403);
+  assert.equal(store.data.audit.length, 2);
+});
+
+test("changes are audited, newest first, for managers", async () => {
+  const { raw } = app();
+  await raw({ method: "POST", path: "/recipes/1/cook", headers: bearer("cook-key-1"), body: { portions: 1 } });
+  await raw({ method: "POST", path: "/temperatures", headers: bearer("manager-key-1"), body: { location: "fridge", celsius: 3 } });
+  const res = await raw({ path: "/audit", headers: bearer("manager-key-1") });
+  assert.equal(res.status, 200);
+  assert.deepEqual(res.body.map((e) => [e.name, e.method, e.path, e.status]), [
+    ["head-chef", "POST", "/temperatures", 201],
+    ["line-cook", "POST", "/recipes/1/cook", 200],
+  ]);
+  assert.ok(res.body[0].at);
+});
